// Lookup over the vendored caniemail slice (src/preview/data/caniemail.json,
// regenerated by scripts/build-caniemail.ts).
import data from './data/caniemail.json';
import { TARGET_CLIENTS, type FeatureSlug, type PlatformKey, type TargetClientId } from './caniemail-spec';
import { detectFeatures, type DetectedFeature } from './features';

export type SupportLevel = 'y' | 'a' | 'n' | 'u';

interface CompactFeature { t: string; u: string; c: string; s: Record<string, string>; n?: Record<string, string> }
export interface CaniemailData { source: string; license: string; updated: string; features: Record<string, CompactFeature> }

export const CANIEMAIL = data as CaniemailData;

export interface Support { level: SupportLevel; notes: string[] }

/** y = supported, a = partial/buggy, n = not supported, u = unknown/untested. */
export function parseSupport(raw: string | undefined, notesByNum: Record<string, string> = {}): Support {
  const v = (raw || 'u').trim();
  const head = v.charAt(0).toLowerCase();
  const level: SupportLevel = head === 'y' || head === 'a' || head === 'n' ? head : 'u';
  const notes = [...v.matchAll(/#(\d+)/g)].map(m => notesByNum[m[1]]).filter((n): n is string => !!n);
  return { level, notes };
}

const SEVERITY: Record<SupportLevel, number> = { y: 0, u: 1, a: 2, n: 3 };

/** Support of one feature in one target client (worst of the platforms it stands for). */
export function supportFor(slug: string, target: TargetClientId, db: CaniemailData = CANIEMAIL): Support {
  const f = db.features[slug];
  if (!f) return { level: 'u', notes: [] };
  const client = TARGET_CLIENTS.find(c => c.id === target);
  if (!client) return { level: 'u', notes: [] };
  let worst: Support = { level: 'y', notes: [] };
  const notes = new Set<string>();
  for (const p of client.platforms as readonly PlatformKey[]) {
    const s = parseSupport(f.s[p], f.n);
    if (s.level !== 'y') s.notes.forEach(n => notes.add(n));
    if (SEVERITY[s.level] > SEVERITY[worst.level]) worst = s;
  }
  return { level: worst.level, notes: worst.level === 'y' ? [] : [...notes] };
}

export interface CompatRow extends DetectedFeature {
  title: string;
  url: string;
  support: Record<TargetClientId, Support>;
  /** Targets where the feature is partial or unsupported. */
  problems: TargetClientId[];
}

/** Detect features in `html` and attach per-client support. Rows with problems first. */
export function compatibilityReport(html: string, db: CaniemailData = CANIEMAIL): CompatRow[] {
  const rows = detectFeatures(html).map(f => {
    const meta = db.features[f.slug];
    const support = Object.fromEntries(TARGET_CLIENTS.map(c => [c.id, supportFor(f.slug, c.id, db)])) as Record<TargetClientId, Support>;
    const problems = TARGET_CLIENTS.filter(c => support[c.id].level === 'a' || support[c.id].level === 'n').map(c => c.id);
    return {
      ...f,
      title: meta?.t ?? f.slug,
      url: meta?.u ?? `https://www.caniemail.com/features/${f.slug}/`,
      support,
      problems,
    };
  });
  const score = (r: CompatRow) => r.problems.reduce((s, id) => s + SEVERITY[r.support[id].level], 0);
  return rows.sort((a, b) => score(b) - score(a));
}

export function featureTitle(slug: FeatureSlug): string {
  return CANIEMAIL.features[slug]?.t ?? slug;
}
